package bo.com.ganadero.potreros.application;
import bo.com.ganadero.potreros.domain.*; import bo.com.ganadero.shared.error.*; import bo.com.ganadero.shared.security.*;
import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class PotreroServiceTest {
 @Test void rejectsSectorFromAnotherProperty(){UUID company=UUID.randomUUID(),property=UUID.randomUUID(),sector=UUID.randomUUID();PotreroRepository repo=mock(PotreroRepository.class);when(repo.propertyExists(property,company)).thenReturn(true);when(repo.sectorBelongs(sector,property,company)).thenReturn(false);CurrentUser user=new CurrentUser(UUID.randomUUID(),company,UUID.randomUUID(),Set.of(),Set.of("POTRERO_CREAR"),Set.of(),true);PotreroService service=new PotreroService(repo,mock(TipoPastoRepository.class),new UserContext(()->user),event->{});PotreroCommand command=new PotreroCommand(property,sector,"P-1","Potrero",null,null,null,false,null,null,true,false,false,false,false,0L);assertThatThrownBy(()->service.create(command)).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.code()).isEqualTo(ErrorCode.SECTOR_NOT_FOUND));verify(repo,never()).create(any(),any());}
 @Test void removesOptionalValuesWhenExplicitlyRequested(){UUID company=UUID.randomUUID(),property=UUID.randomUUID(),sector=UUID.randomUUID(),grass=UUID.randomUUID(),id=UUID.randomUUID();PotreroRepository repo=mock(PotreroRepository.class);Potrero old=new Potrero(id,company,property,sector,"P-1","Potrero",java.math.BigDecimal.TEN,grass,java.math.BigDecimal.ONE,true,EstadoPotrero.DISPONIBLE,null,true,4L);when(repo.findById(id,company)).thenReturn(Optional.of(old));when(repo.propertyExists(property,company)).thenReturn(true);when(repo.update(any(),any(),eq(true),eq(true),eq(true),eq(true))).thenAnswer(invocation->invocation.getArgument(0));CurrentUser user=new CurrentUser(UUID.randomUUID(),company,UUID.randomUUID(),Set.of(),Set.of("POTRERO_EDITAR"),Set.of(),true);PotreroService service=new PotreroService(repo,mock(TipoPastoRepository.class),new UserContext(()->user),event->{});PotreroCommand command=new PotreroCommand(null,null,"P-1","Potrero",null,null,null,true,EstadoPotrero.DISPONIBLE,null,true,true,true,true,true,4L);Potrero updated=service.update(id,command);assertThat(updated.sectorId()).isNull();assertThat(updated.tipoPastoId()).isNull();assertThat(updated.superficieHa()).isNull();assertThat(updated.capacidadUa()).isNull();verify(repo).update(any(),any(),eq(true),eq(true),eq(true),eq(true));}
}
